param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'type-signature-argument-snapshots-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture




function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}



function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
function Value($value,$self){if($null -eq $value){return $null};if($value -is [Type]){if([object]::ReferenceEquals($value,$self)){return 'self'};return 'type:'+$value.ToString()};if($value -is [bool]){return $value.ToString().ToLowerInvariant()};if($value -is [Enum]){return ([int]$value).ToString()};if($value -is [Array]){return (($value|ForEach-Object {Value $_ $self})-join ';')};return $value.ToString()}
function Resolve($name){$list=[object].Assembly.GetType('System.Collections.Generic.List`1');$dict=[object].Assembly.GetType('System.Collections.Generic.Dictionary`2');$nullable=[object].Assembly.GetType('System.Nullable`1');switch($name){'null'{return $null};'ListD'{return $list};'DictD'{return $dict};'NullableD'{return $nullable};'TupleD'{return [object].Assembly.GetType('System.ValueTuple`2')};'ListS'{return $list.MakeGenericType([type[]]@([string]))};'Sig0'{return [Type]::MakeGenericMethodParameter(0)};'Sig1'{return [Type]::MakeGenericMethodParameter(1)};'Sig0Array'{return [Type]::MakeGenericMethodParameter(0).MakeArrayType()};'Sig0Ref'{return [Type]::MakeGenericMethodParameter(0).MakeByRefType()};'SigList'{return [Type]::MakeGenericSignatureType($list,[type[]]@([Type]::MakeGenericMethodParameter(0)))};default{return [Type]::GetType('System.'+$name,$true,$false)}}}
function Construct($mode,$definition,$arguments){$invoke=[object[]]::new(2);if($mode -eq 'static'){$invoke[0]=$definition;$invoke[1]=$arguments;return [Type].GetMethod('MakeGenericSignatureType',[type[]]@([type],[type[]])).Invoke($null,$invoke)};$invoke=[object[]]::new(1);$invoke[0]=$arguments;return [Type].GetMethod('MakeGenericType',[type[]]@([type[]])).Invoke($definition,$invoke)}
function Snapshot($type,$definition,$saved){$read=$type.GetGenericArguments();$prop=$type.GenericTypeArguments;$same=$read.Length -eq $saved.Length -and $prop.Length -eq $saved.Length;for($i=0;$i -lt $saved.Length;$i++){$same=$same -and [object]::ReferenceEquals($read[$i],$saved[$i]) -and [object]::ReferenceEquals($prop[$i],$saved[$i])};return ([string]$same.ToString().ToLowerInvariant())+'|'+$type.ToString()+'|'+$type.Name+'|'+$type.Namespace+'|'+$type.ContainsGenericParameters.ToString().ToLowerInvariant()+'|'+[object]::ReferenceEquals($type.GetGenericTypeDefinition(),$definition).ToString().ToLowerInvariant()}
function Mutation($op,$type,$definition,$arguments,$saved){if($op.StartsWith('Mutate:')){$parts=$op.Split(':');$array=$null;switch($parts[1]){'Input'{$array=$arguments};'Arguments'{$array=$type.GetGenericArguments()};'Property'{$array=$type.GenericTypeArguments}};$index=[int]$parts[3];if($index -ge $array.Length){return 'no-slot'};$before=$array[$index];$replacement=$null;switch($parts[2]){'Runtime'{$replacement=[string]};'Signature'{$replacement=[Type]::MakeGenericMethodParameter(255)}};try{$array[$index]=$replacement;return Snapshot $type $definition $saved}finally{$array[$index]=$before}};switch($op){'InputAlias'{return [object]::ReferenceEquals($arguments,$type.GetGenericArguments())};'ReadAlias'{return [object]::ReferenceEquals($type.GetGenericArguments(),$type.GetGenericArguments())};'PropertyAlias'{return [object]::ReferenceEquals($type.GenericTypeArguments,$type.GenericTypeArguments)};'CrossAlias'{return [object]::ReferenceEquals($type.GetGenericArguments(),$type.GenericTypeArguments)};'DefinitionIdentity'{return [object]::ReferenceEquals($type.GetGenericTypeDefinition(),$definition)}};throw 'unknown operation'}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new();$constructors=[Collections.Generic.List[object]]::new();$flags=[Reflection.BindingFlags]'Public,Instance'
foreach($case in $plan.cases){$position=0;$definition=Resolve $case.definition;$arguments=$null;if($case.arguments -is [string]){if($null -eq $definition){$arguments=[type[]]::new(0)}else{$arguments=$definition.GetGenericArguments()}}elseif($null -ne $case.arguments){$arguments=[type[]]::new($case.arguments.Count);for($i=0;$i -lt $arguments.Length;$i++){if($null -ne $case.arguments[$i]){$arguments[$i]=Resolve $case.arguments[$i]}}};$saved=$null;if($null -ne $arguments){$saved=$arguments.Clone()};$type=$null;$errorName='none';$message=$null;$hResult=0;$param=$null;try{$type=Construct $case.mode $definition $arguments}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$constructors.Add([ordered]@{id=$case.id;position=[int]$position;valueUnits=(Units $(if($null -ne $type){$(if($type.IsSignatureType){'signature:'}else{'runtime:'})+$type.ToString()}else{$null}));exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param)});if($null -eq $type -or -not $type.IsSignatureType){continue}
foreach($op in $plan.operations){$errorName='none';$message=$null;$hResult=0;$param=$null;$value=$null;try{$result=Mutation $op $type $definition $arguments $saved;$value=Value $result $type;if($op -eq 'P:GenericTypeArguments'){$value=Value ([Type].GetProperty('GenericTypeArguments').GetValue($type)) $type}elseif($op -in @('GetGenericArguments','GetOptionalCustomModifiers','GetRequiredCustomModifiers')){$value=Value ([Type].GetMethod($op,[type[]]@()).Invoke($type,[object[]]@())) $type}}catch{$errorValue=$_.Exception;while($errorValue -is [Reflection.TargetInvocationException] -or $errorValue -is [Management.Automation.MethodInvocationException]){$errorValue=$errorValue.InnerException};$errorName=$errorValue.GetType().FullName;$message=$errorValue.Message;$hResult=$errorValue.HResult;if($errorValue -is [ArgumentException]){$param=$errorValue.ParamName}};$rows.Add([ordered]@{id=$case.id;position=[int]$position;operation=$op;valueUnits=(Units $value);exception=$errorName;messageUnits=(Units $message);hResult=$hResult;paramUnits=(Units $param)})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();constructors=$constructors.ToArray();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS signature parameter capture: $($constructors.Count) constructors and $($rows.Count) operations"
